1:// Part 7, Grounds and lights (lamp posts, woodpiles on the pavement flanks and in the cart passage edges).
2-// The paving itself is the shell's (pavingPatch in parts/shell.mjs); this part adds only what stands on it.
3-// Woodpiles sit on the pavement top (planks at y 5) and keep out of the clear zones (x 9..33, z 4..5 and 32..33, y 6..8).
4-// South piles mirror the north ones by z -> 37 - z (the pile's outer cell row moves from z 0..1 to z 36..37).
5-import { lampPost, woodPile } from "../vocab.mjs";
6-
7-const mirrorZ = (z) => 37 - z;
8-
9-export function build(g) {
10-  const report = [];
11-  const log = (name, out) => report.push([name, out.placed, out.refused.length]);
12-
13-  // lamp posts: fence posts with a lantern on top, at x 1 and 41, z 1 and 36 (plan SITE: outside every clear zone)
--
26:  // cart passage edges: x 35..36 only, so the lane x 37 stays open through the block
27:  log("birch passage", woodPile(g, 35, 5, 10, 5, "birch", { axis: "z" }));
28:  log("dark oak passage", woodPile(g, 35, 5, 22, 5, "dark_oak", { axis: "z" }));
29-
30-  const refused = report.filter(([, , r]) => r > 0);
31-  for (const [name, placed, r] of report) console.log(`  grounds: ${name}: ${placed} placed, ${r} refused`);
32-  if (refused.length) console.log(`  grounds: refused in ${refused.map(([n]) => n).join(", ")}`);
33-}
